            var rows=model.Proposals.Select(p=>new ComparisonDisplay(p,model.Input,model.Settings)).ToArray();var comparison=Table(rows,"Scenario|Id|75","Types|Types|60","Panels|Panels|70","Stock m|Stock|90","Groups|Groups|75","Mean use %|Mean|100","Min use %|Minimum|100","Filler locations|Fillers|110","Panel changes|Changes|110","Actual offer %|Actual|110","Target delta m|Delta|110","Pareto|Pareto|80","Status|Status|*");comparison.Margin=new Thickness(0,6,0,6);comparison.SelectedItem=rows.FirstOrDefault(r=>r.Proposal==selected);comparison.SelectionChanged+=(s,e)=>{if(!rendering&&comparison.SelectedItem is ComparisonDisplay row)model.Selected=row.Proposal;};Grid.SetRow(comparison,3);grid.Children.Add(comparison);
            var stock=Table(selected.Stock.OrderBy(p=>p.Key).Select(p=>new{Length=(p.Key/1000m).ToString("F2",CultureInfo.InvariantCulture),Quantity=p.Value,Total=(p.Key*p.Value/1000m).ToString("F3",CultureInfo.InvariantCulture),Kit=selected.IdenticalKitCount>0?(p.Value/selected.IdenticalKitCount).ToString():"—"}).ToArray(),"Nominal length m|Length|140","Stock quantity|Quantity|140","Total m|Total|100","Per kit (if identical)|Kit|*");Grid.SetRow(stock,4);grid.Children.Add(stock);
            var diagnostic=new TextBox{Text="feasible / best found\n"+selected.RetainedModelStatus+" in retained-pattern model\nRetained model objective: "+selected.RetainedObjective+"; bound "+selected.RetainedBound+". Not a global design-space proof.\n"+string.Join("\n",model.SearchLog),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,FontSize=12,Margin=new Thickness(0,6,0,0),Padding=new Thickness(8),BorderBrush=Line};Grid.SetRow(diagnostic,5);grid.Children.Add(diagnostic);return grid;
        }
        private UIElement CastingPage()
        {
            var p=model.Selected;if(p==null)return Notice("Select a validated proposal to inspect casting groups.");var grid=new Grid();foreach(var h in new[]{GridLength.Auto,new GridLength(365),GridLength.Auto,new GridLength()})grid.RowDefinitions.Add(new RowDefinition{Height=h});grid.Children.Add(Notice("Equipment allocation groups • no spatial adjacency, site zones, pouring dates or certified construction order is implied."));
            var rows=p.Groups.Select((g,i)=>new GroupDisplay(g,p,i)).ToArray();var groups=Table(rows,"Group|Id|70","Walls|Count|60","Installed m|Installed|100","Use %|Use|85","Direct locations|Direct|120","Filler locations|Fillers|120","Wall IDs|Ids|*");groups.Margin=new Thickness(0,6,0,0);castingIndex=Math.Min(castingIndex,rows.Length-1);groups.SelectedIndex=Math.Max(0,castingIndex);Grid.SetRow(groups,1);grid.Children.Add(groups);
            var detail=Label("",12,Muted,null,new Thickness(0,7,0,6));Grid.SetRow(detail,2);grid.Children.Add(detail);var diagrams=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,BorderBrush=Line,BorderThickness=new Thickness(1)};Grid.SetRow(diagrams,3);grid.Children.Add(diagrams);
            Action update=()=>{if(groups.SelectedItem is GroupDisplay row){castingIndex=row.Index;model.SelectedGroupIndex=castingIndex;detail.Text="Used / idle by type: "+string.Join(", ",p.Stock.OrderBy(s=>s.Key).Select(s=>{int used=row.Group.Walls.Sum(a=>a.Pattern.PanelsMm.Count(n=>n==s.Key));return (s.Key/1000m).ToString("0.##",CultureInfo.InvariantCulture)+" m: "+used+" / "+(s.Value-used);}))+"\n"+ConnectorAllocation.Calculate(p,model.Settings).Description;diagrams.Content=new Top50Diagram(row.Group);}};groups.SelectionChanged+=(s,e)=>update();update();return grid;
        }
        private UIElement ReportsPage()
        {
            var root=new DockPanel{LastChildFill=true};var stack=new StackPanel();var p=model.Selected;stack.Children.Add(Group("One consistent workbook",Label(p==null?"Select a validated proposal first.":"Export selected alternative "+p.Id+": "+p.Groups.Count+" validated mathematical groups.\nOne workbook, nine worksheets. Source audit, precise arrangements, stock and idle quantities, connector locations/units, comparison and engineering checks.\n\n"+ConnectorAllocation.Calculate(p,model.Settings).Description+"\n\n"+Disclaimer,12)));
            var export=Action("Export selected solution to Excel…",Export,true);export.IsEnabled=p!=null&&!model.IsStale;export.HorizontalAlignment=HorizontalAlignment.Stretch;export.Margin=new Thickness(0,0,0,6);stack.Children.Add(export);DockPanel.SetDock(stack,Dock.Top);root.Children.Add(stack);root.Children.Add(Card(Label(string.Join("\n",Top50Workbook.SheetNames.Select((n,i)=>(i+1).ToString("00")+"  "+n)),13),new Thickness(10)));return root;
        }
        private void ImportDxf(){if(!ConfirmDiscard())return;var dialog=new OpenFileDialog{Title="Import DXF wall dimensions",Filter="DXF drawings (*.dxf)|*.dxf"};if(dialog.ShowDialog(this)==true)try{var options=new DxfImportOptions();if(unitsChoice!=0){string reason=AskText("Reviewed source units","Reason for the explicit units conversion","");if(reason==null)return;options.MmPerUnitOverride=unitsChoice==1?1:1000;options.OverrideReason=reason;}model.Import(dialog.FileName,options);ShowPage(0);}catch(Exception e){Error(e);}}
        private void AddManual(){string length=AskText("Add manual wall","Reviewed wall length in millimetres","");if(length==null)return;string reason=AskText("Manual wall source","Source / engineering review reason","");if(reason==null)return;try{model.AddManual(decimal.Parse(length,CultureInfo.InvariantCulture),reason);ShowPage(0);}catch(Exception e){Error(e);}}
        private string AskText(string title,string label,string initial){var dialog=new Window{Title=title,Owner=this,Width=570,Height=190,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner};var stack=new StackPanel{Margin=new Thickness(20)};stack.Children.Add(Label(label));var text=new TextBox{Text=initial,Margin=new Thickness(0,10,0,10)};stack.Children.Add(text);var ok=new Button{Content="OK",IsDefault=true};ok.Click+=(s,e)=>dialog.DialogResult=true;stack.Children.Add(ok);dialog.Content=stack;return dialog.ShowDialog()==true?text.Text:null;}
        private void OpenProject(){if(!ConfirmDiscard())return;var dialog=new OpenFileDialog{Title="Open Top50 project",Filter="Top50 projects (*.top50)|*.top50"};if(dialog.ShowDialog(this)==true)try{model.Open(dialog.FileName,System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DokaTop50Native","sources"));ShowPage(0);}catch(Exception e){Error(e);}}
        private void SaveProject(){var dialog=new SaveFileDialog{Title="Save Top50 project",Filter="Top50 projects (*.top50)|*.top50",FileName=model.ProjectPath??"Top50 project.top50"};if(dialog.ShowDialog(this)==true)try{model.Save(dialog.FileName);}catch(Exception e){Error(e);}}
        private void Export(){var dialog=new SaveFileDialog{Title="Export selected solution",Filter="Excel workbook (*.xlsx)|*.xlsx",FileName="Top50 planning report.xlsx"};if(dialog.ShowDialog(this)==true)try{model.Export(dialog.FileName);}catch(Exception e){Error(e);}}
        private bool ConfirmDiscard()=>!model.Dirty||MessageBox.Show(this,"Discard unsaved changes? Save the project first to keep them.","Top50 project",MessageBoxButton.OKCancel,MessageBoxImage.Question)==MessageBoxResult.OK;
        private void Review(WallRow wall)
        {
            var dialog=new Window{Title="Review "+wall.Id,Owner=this,Width=650,Height=370,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize};var stack=new StackPanel{Margin=new Thickness(20)};stack.Children.Add(Label(string.Join("\n",wall.Diagnostics)+"\nProjected raw mm: "+wall.ProjectedRawMm+"; aligned endpoint distance mm: "+wall.EndpointDistanceMm+"; stored: "+wall.StoredMeasurementMm,12,Muted));var length=new TextBox{Text=wall.LengthMm.ToString(CultureInfo.InvariantCulture),Margin=new Thickness(0,12,0,6)};stack.Children.Add(FormRow("Reviewed length mm",length));var include=new CheckBox{Content="Include this reviewed wall",IsChecked=wall.Included};stack.Children.Add(include);var reason=new TextBox{Margin=new Thickness(0,8,0,8)};stack.Children.Add(FormRow("Explicit review reason",reason));var ok=new Button{Content="Apply review",IsDefault=true};ok.Click+=(s,e)=>{try{wall.Review(decimal.Parse(length.Text,CultureInfo.InvariantCulture),include.IsChecked==true,reason.Text);dialog.DialogResult=true;}catch(Exception ex){model.RecordDiagnosticError("Review wall "+wall.Id,ex);MessageBox.Show(dialog,ex.Message);}};stack.Children.Add(ok);dialog.Content=stack;if(dialog.ShowDialog()==true){model.Changed();ShowPage(0);}
        }
        private void ModelChanged(object sender,PropertyChangedEventArgs e){if(!Dispatcher.CheckAccess()){Dispatcher.BeginInvoke(new Action(()=>ModelChanged(sender,e)));return;}if(e.PropertyName==nameof(Top50ViewModel.Status)||e.PropertyName==nameof(Top50ViewModel.IsBusy))UpdateBusy();if(e.PropertyName==nameof(Top50ViewModel.Input)||e.PropertyName==nameof(Top50ViewModel.Proposals)||e.PropertyName==nameof(Top50ViewModel.Selected)||e.PropertyName==nameof(Top50ViewModel.Settings)){if(renderQueued)return;renderQueued=true;Dispatcher.BeginInvoke(new Action(()=>{renderQueued=false;ShowPage(page);}));}}
        private void UpdateBusy(){bool busy=model.IsBusy;cancel.IsEnabled=busy;optimize.IsEnabled=!busy;open.IsEnabled=!busy;save.IsEnabled=!busy;content.IsEnabled=!busy;progress.Text=model.Status;progress.Visibility=busy||model.IsStale?Visibility.Visible:Visibility.Collapsed;}
        private void OnClosing(object sender,CancelEventArgs e){if(model.IsBusy){model.Cancel();e.Cancel=true;return;}if(!ConfirmDiscard())e.Cancel=true;else model.PropertyChanged-=ModelChanged;}
        private void Error(Exception error){model.RecordDiagnosticError("Planner action",error);ShowError(error.Message);}
        private void Error(string message){model.RecordDiagnosticError("Edit planner settings",new ArgumentException(message));ShowError(message);}
        private void ShowError(string message)=>MessageBox.Show(this,message,"Top50 Planner",MessageBoxButton.OK,MessageBoxImage.Information);
        private sealed class UniformGridProxy : System.Windows.Controls.Primitives.UniformGrid{public UniformGridProxy(int columns){Columns=columns;}}
        private sealed class AlternativeChoice{public Proposal Proposal{get;}public string Label=>Proposal.Id+" • rank "+Proposal.Rank+" • feasible / best found";public AlternativeChoice(Proposal proposal){Proposal=proposal;}}
        private sealed class ImportDisplay
        {
            public WallRow Wall{get;}public string Id=>Wall.Id;public bool Included=>Wall.Included;public bool Acknowledged=>Wall.Acknowledged;public string Length=>Wall.LengthMm.ToString("F3",CultureInfo.InvariantCulture);public string Raw=>Wall.ProjectedRawMm.ToString(CultureInfo.InvariantCulture);public string Stored=>Wall.StoredMeasurementMm?.ToString(CultureInfo.InvariantCulture)??"";public string Layer=>Wall.Layer;public string Diagnostics=>Wall.Status==WallReviewStatus.Valid?"Valid":string.Join("; ",Wall.Diagnostics);public ImportDisplay(WallRow wall){Wall=wall;}
        }
        private sealed class ComparisonDisplay
        {
            public Proposal Proposal{get;}private readonly ImportSnapshot input;private readonly NativeTop50Project settings;public string Id=>Proposal.Id;public int Types=>Proposal.Stock.Count;public int Panels=>Proposal.PanelCount;public string Stock=>(Proposal.StockMicrometres/1000000m).ToString("F3",CultureInfo.InvariantCulture);public int Groups=>Proposal.Groups.Count;public string Mean=>(Proposal.MeanUtilization*100).ToString("F2",CultureInfo.InvariantCulture);public string Minimum=>(Proposal.MinimumUtilization*100).ToString("F2",CultureInfo.InvariantCulture);public int Fillers=>Proposal.FillerLocations;public int Changes=>Proposal.PanelChanges;public string Actual=>(Proposal.StockMicrometres/(input.Walls.Where(w=>w.Included).Sum(w=>(decimal)w.LengthMicrometres))*100).ToString("F2",CultureInfo.InvariantCulture);public string Delta=>settings.OfferingMode==0?"—":((Proposal.StockMicrometres-input.Walls.Where(w=>w.Included).Sum(w=>(decimal)w.LengthMicrometres)*settings.Percentage/100)/1000000m).ToString("+0.000;-0.000;0.000",CultureInfo.InvariantCulture);public bool Pareto=>Proposal.Pareto;public string Status=>"feasible / best found";public ComparisonDisplay(Proposal p,ImportSnapshot input,NativeTop50Project settings){Proposal=p;this.input=input;this.settings=settings;}
        }
        private sealed class GroupDisplay
        {
            public CastingGroup Group{get;}public int Index{get;}private readonly Proposal proposal;public string Id=>"G"+(Index+1).ToString("00");public int Count=>Group.Walls.Count;public string Installed=>(Group.InstalledPanelMicrometres/1000000m).ToString("F3",CultureInfo.InvariantCulture);public string Use=>((decimal)Group.InstalledPanelMicrometres/proposal.StockMicrometres*100).ToString("F2",CultureInfo.InvariantCulture);public int Direct=>Group.Walls.Sum(a=>a.Pattern.DirectLocations);public int Fillers=>Group.Walls.Sum(a=>a.Pattern.FillerLocations);public string Ids=>string.Join(", ",Group.Walls.Select(a=>a.WallId));public GroupDisplay(CastingGroup group,Proposal proposal,int index){Group=group;this.proposal=proposal;Index=index;}
        }
    }
    public sealed class Top50Diagram : FrameworkElement
    {
        private readonly CastingGroup group;
        public Top50Diagram(CastingGroup group){this.group=group;MinHeight=group.Walls.Count*72+20;HorizontalAlignment=HorizontalAlignment.Stretch;}
        protected override Size MeasureOverride(Size available)=>new Size(double.IsInfinity(available.Width)?900:available.Width,MinHeight);
        protected override void OnRender(DrawingContext dc)
        {
            double start=180,width=Math.Max(200,ActualWidth-start-70),maximum=group.Walls.Max(w=>w.Pattern.LengthMicrometres);double scale=width/maximum;double y=20;
            foreach(var wall in group.Walls)
            {
                DrawText(dc,wall.WallId,12,Top50Window.Navy,12,y+4);double x=start;
                for(int i=0;i<wall.Pattern.PanelsMm.Count;i++)
                {
                    int size=wall.Pattern.PanelsMm[i];double segment=size*1000*scale;dc.DrawRectangle(new SolidColorBrush(System.Windows.Media.Color.FromRgb(86,125,151)),null,new Rect(x,y,segment,24));DrawText(dc,size.ToString(CultureInfo.InvariantCulture),12,Brushes.White,x+Math.Max(0,(segment-35)/2),y+4);x+=segment;
                    if(i<wall.Pattern.InternalGapsMicrometres.Count){double gap=wall.Pattern.InternalGapsMicrometres[i]*scale;if(gap>0)dc.DrawRectangle(new SolidColorBrush(System.Windows.Media.Color.FromRgb(224,165,64)),null,new Rect(x,y,gap,24));x+=gap;}
                }
                DrawText(dc,string.Join(" + ",wall.Pattern.PanelsMm)+" mm | "+string.Join(", ",wall.Pattern.InternalGapsMicrometres.Select((gap,index)=>new{gap,index}).Where(v=>v.gap>0).Select(v=>"filler after panel "+(v.index+1)+": "+(v.gap/1000m).ToString(CultureInfo.InvariantCulture)+" mm")),12,Top50Window.Muted,start,y+31);y+=72;
            }
        }
        private void DrawText(DrawingContext dc,string text,double size,Brush brush,double x,double y)=>dc.DrawText(new FormattedText(text,CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),size,brush,VisualTreeHelper.GetDpi(this).PixelsPerDip),new Point(x,y));
    }
